<script setup>
import { computed, ref } from 'vue';

const props = defineProps({ page: String, payload: Object, user: Object, errors: Array, flash: String });
const csrf = document.querySelector('meta[name="csrf-token"]').content;
const tab = ref('orders');
const edit = ref(null);
const search = new URLSearchParams(location.search);
const items = computed(() => props.payload.listings?.data ?? props.payload.listings ?? []);
const money = n => new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB' }).format(n);
const date = s => new Date(s).toLocaleDateString('ru-RU');
const image = path => path ? '/storage/' + path : '';
const status = { active: 'Активно', paused: 'На паузе', hidden: 'Скрыто', pending_payment: 'Ожидает тестовой оплаты', awaiting_delivery: 'Ожидает передачи', delivered: 'Передано', completed: 'Завершён', cancelled: 'Отменён', disputed: 'Спор', open: 'Открыт', resolved: 'Решён' };
const kinds = { item: 'Предметы', account: 'Аккаунты', currency: 'Валюта', service: 'Услуги', other: 'Другое' };
</script>

<template>
  <header class="top"><div class="wrap nav"><a class="logo" href="/">✦ Game<span>Goods</span></a><a href="/">Каталог</a><span class="spacer"></span><template v-if="user"><a href="/messages">Сообщения</a><a href="/dashboard">Личный кабинет</a><a v-if="user.is_admin" href="/admin">Админ</a><form action="/logout" method="post"><input type="hidden" name="_token" :value="csrf"><button class="link">Выйти</button></form></template><template v-else><a href="/login">Войти</a><a class="btn small" href="/register">Регистрация</a></template></div></header>
  <main class="wrap">
    <div v-if="flash" class="notice">{{ flash }}</div><div v-for="e in errors" :key="e" class="error">{{ e }}</div>

    <template v-if="page === 'catalog'"><section class="hero"><div><span class="eyebrow">МАРКЕТПЛЕЙС ИГРОВЫХ ТОВАРОВ</span><h1>Твой следующий уровень<br>начинается здесь.</h1><p>Предметы, аккаунты, валюта и услуги от игроков. Демо-покупки без реальной оплаты.</p></div><div class="hero-icon">✦</div></section>
      <div class="layout"><aside class="panel filters"><h3>Фильтры</h3><form action="/" method="get"><label>Поиск<input name="q" :value="search.get('q')" placeholder="Игра или товар"></label><label>Категория<select name="category"><option value="">Все категории</option><option v-for="c in payload.categories" :key="c.id" :value="c.slug" :selected="search.get('category') === c.slug">{{ c.name }}</option></select></label><label>Тип<select name="kind"><option value="">Все типы</option><option v-for="(name,key) in kinds" :value="key" :selected="search.get('kind') === key">{{ name }}</option></select></label><div class="row"><label>От<input name="min" type="number" min="0" :value="search.get('min')"></label><label>До<input name="max" type="number" min="0" :value="search.get('max')"></label></div><label>Сортировка<select name="sort"><option value="">Новые</option><option value="cheap" :selected="search.get('sort') === 'cheap'">Сначала дешёвые</option><option value="expensive" :selected="search.get('sort') === 'expensive'">Сначала дорогие</option><option value="oldest" :selected="search.get('sort') === 'oldest'">Сначала старые</option></select></label><button class="btn full">Показать</button></form></aside><section class="results"><div class="section-head"><h2>Объявления</h2><a v-if="user" href="/dashboard" class="btn outline">+ Продать товар</a></div><div class="grid"><a v-for="l in items" :key="l.id" :href="'/listings/'+l.id" class="card"><div class="thumb"><img v-if="l.image" :src="image(l.image)" alt=""><span v-else>✦</span></div><div class="card-body"><span class="tag">{{ l.category?.name }} · {{ kinds[l.kind] }}</span><h3>{{ l.title }}</h3><p>{{ l.game || 'Игровые товары' }}</p><div class="card-bottom"><strong>{{ money(l.price) }}</strong><small>{{ l.user?.name }}</small></div></div></a></div><p v-if="!items.length" class="empty">Пока нет объявлений. Создайте первое!</p><nav v-if="payload.listings?.last_page > 1" class="pagination"><a v-for="p in payload.listings.last_page" :key="p" :class="{ current: p === payload.listings.current_page }" :href="'/?'+new URLSearchParams([...search].filter(([k])=>k!=='page').concat([['page',p]])).toString()">{{ p }}</a></nav></section></div>
    </template>

    <template v-else-if="page === 'listing'"><a class="back" href="/">← Все объявления</a><div class="detail"><div class="panel"><div class="detail-image"><img v-if="payload.listing.image" :src="image(payload.listing.image)" alt=""><span v-else>✦</span></div><div class="pad"><span class="tag">{{ payload.listing.category.name }} · {{ kinds[payload.listing.kind] }}</span><h1>{{ payload.listing.title }}</h1><p class="muted">{{ payload.listing.game }} · Осталось: {{ payload.listing.stock }}</p><h3>Описание</h3><p class="description">{{ payload.listing.description }}</p></div></div><aside><div class="panel pad"><div class="price">{{ money(payload.listing.price) }}</div><p class="muted">Демо-покупка: деньги не списываются</p><form v-if="user && user.id !== payload.listing.user_id" :action="'/listings/'+payload.listing.id+'/orders'" method="post"><input type="hidden" name="_token" :value="csrf"><button class="btn full" :disabled="!payload.listing.stock">Оформить заказ</button></form><a v-else-if="!user" class="btn full" href="/login">Войти для покупки</a><form v-if="user" :action="'/listings/'+payload.listing.id+'/favorite'" method="post"><input type="hidden" name="_token" :value="csrf"><button class="btn outline full">♡ Избранное</button></form></div><div class="panel pad seller-box"><p class="muted">Продавец</p><a :href="'/sellers/'+payload.listing.user_id"><strong>{{ payload.listing.user.name }}</strong></a><a v-if="user && user.id !== payload.listing.user_id" :href="'/messages/'+payload.listing.user_id">Написать продавцу →</a></div><div class="panel pad"><h3>Отзывы о продавце</h3><div v-for="r in payload.reviews" :key="r.id" class="review"><strong>{{ '★'.repeat(r.rating) }}{{ '☆'.repeat(5-r.rating) }}</strong> {{ r.author.name }}<p>{{ r.body }}</p></div><p v-if="!payload.reviews.length" class="muted">Отзывов пока нет</p></div></aside></div></template>

    <template v-else-if="page === 'checkout'"><div class="auth panel pad"><span class="tag">ТЕСТОВАЯ ОПЛАТА</span><h1>Заказ #{{ payload.order.id }}</h1><p>{{ payload.order.listing.title }}</p><div class="price">{{ money(payload.order.price) }}</div><p class="muted">Симулятор оплаты. Банковские реквизиты не требуются и реальные деньги не списываются.</p><form :action="'/orders/'+payload.order.id+'/pay'" method="post"><input type="hidden" name="_token" :value="csrf"><button class="btn full" name="outcome" value="success">Подтвердить тестовую оплату</button><button class="btn outline full" name="outcome" value="decline">Имитировать отказ</button></form><form :action="'/orders/'+payload.order.id+'/cancel'" method="post"><input type="hidden" name="_token" :value="csrf"><button class="link">Отменить заказ</button></form></div></template>

    <template v-else-if="page === 'login' || page === 'register'"><div class="auth panel pad"><h1>{{ page === 'login' ? 'С возвращением' : 'Создать аккаунт' }}</h1><p class="muted">Продолжайте исследовать игровой маркетплейс</p><form :action="'/'+page" method="post"><input type="hidden" name="_token" :value="csrf"><label v-if="page === 'register'">Имя<input name="name" required maxlength="80" autocomplete="name"></label><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Пароль<input type="password" name="password" required minlength="8" :autocomplete="page === 'login' ? 'current-password' : 'new-password'"></label><label v-if="page === 'register'">Повторите пароль<input type="password" name="password_confirmation" required minlength="8"></label><label v-if="page === 'login'" class="check"><input type="checkbox" name="remember" value="1"> Запомнить меня</label><button class="btn full">{{ page === 'login' ? 'Войти' : 'Зарегистрироваться' }}</button></form><p><a :href="page === 'login' ? '/register' : '/login'">{{ page === 'login' ? 'Нет аккаунта? Зарегистрируйтесь' : 'Уже есть аккаунт? Войдите' }}</a></p></div></template>

    <template v-else-if="page === 'seller'"><a class="back" href="/">← Каталог</a><div class="panel pad"><h1>{{ payload.seller.name }}</h1><p class="muted">На площадке с {{ date(payload.seller.created_at) }}</p><p class="description">{{ payload.seller.bio || 'Продавец ещё не добавил описание.' }}</p><a v-if="user && user.id !== payload.seller.id" :href="'/messages/'+payload.seller.id" class="btn outline">Написать</a></div><h2>Объявления</h2><div class="grid"><a v-for="l in items" :key="l.id" class="card pad" :href="'/listings/'+l.id"><span class="tag">{{ kinds[l.kind] }}</span><h3>{{ l.title }}</h3><strong>{{ money(l.price) }}</strong></a></div><h2>Отзывы</h2><div v-for="r in payload.reviews" :key="r.id" class="panel pad review"><strong>{{ '★'.repeat(r.rating) }} {{ r.author.name }}</strong><p>{{ r.body }}</p></div></template>

    <template v-else-if="page === 'inbox'"><h1>Сообщения</h1><a v-for="peer in payload.peers" :key="peer.id" class="panel pad inbox-peer" :href="'/messages/'+peer.id">{{ peer.name }} <span>Открыть переписку →</span></a><p v-if="!payload.peers.length" class="empty">Переписок пока нет. Напишите продавцу через объявление.</p></template>

    <template v-else-if="page === 'messages'"><a class="back" href="/messages">← Сообщения</a><h1>Чат с {{ payload.peer.name }}</h1><div class="panel chat"><div v-for="m in payload.messages" :key="m.id" class="bubble" :class="{ mine: m.sender_id === user.id }"><span>{{ m.body }}</span><small>{{ date(m.created_at) }}</small></div><p v-if="!payload.messages.length" class="empty">Начните разговор</p></div><form class="panel pad" :action="'/messages/'+payload.peer.id" method="post"><input type="hidden" name="_token" :value="csrf"><textarea name="body" required maxlength="5000" placeholder="Ваше сообщение..."></textarea><button class="btn">Отправить</button></form></template>

    <template v-else-if="page === 'dashboard'"><h1>Личный кабинет</h1><p class="muted">Добро пожаловать, {{ user.name }}</p><div class="tabs"><button v-for="t in [['orders','Заказы'],['listings','Мои объявления'],['create','Продать'],['favorites','Избранное'],['profile','Профиль']]" :key="t[0]" :class="{ selected: tab === t[0] }" @click="tab=t[0]">{{ t[1] }}</button></div>
      <section v-if="tab === 'orders'"><div v-for="o in payload.orders" :key="o.id" class="panel pad order"><div class="section-head"><div><span class="tag">Заказ #{{ o.id }} · {{ status[o.status] }}</span><h3><a :href="'/listings/'+o.listing_id">{{ o.listing.title }}</a></h3><p>Покупатель: {{ o.buyer.name }} · Продавец: {{ o.seller.name }}</p></div><strong>{{ money(o.price) }}</strong></div><p v-if="o.delivery_note && (o.buyer_id === user.id || o.seller_id === user.id)" class="description"><strong>Данные передачи:</strong> {{ o.delivery_note }}</p><div class="actions"><a :href="'/messages/'+(o.buyer_id === user.id ? o.seller_id : o.buyer_id)">Открыть чат →</a><a v-if="o.buyer_id === user.id && o.status === 'pending_payment'" class="btn small" :href="'/orders/'+o.id+'/checkout'">Перейти к оплате</a><form v-if="o.buyer_id === user.id && o.status === 'delivered'" :action="'/orders/'+o.id+'/complete'" method="post"><input type="hidden" name="_token" :value="csrf"><button class="btn small">Подтвердить получение</button></form><form v-if="o.buyer_id === user.id && ['pending_payment','awaiting_delivery'].includes(o.status)" :action="'/orders/'+o.id+'/cancel'" method="post"><input type="hidden" name="_token" :value="csrf"><button class="btn outline small">Отменить</button></form></div><form v-if="o.seller_id === user.id && o.status === 'awaiting_delivery'" :action="'/orders/'+o.id+'/deliver'" method="post"><input type="hidden" name="_token" :value="csrf"><label>Данные для покупателя<textarea name="delivery_note" required maxlength="10000" placeholder="Как получить товар"></textarea></label><button class="btn small">Передать заказ</button></form><form v-if="['awaiting_delivery','delivered'].includes(o.status)" :action="'/orders/'+o.id+'/dispute'" method="post"><input type="hidden" name="_token" :value="csrf"><label>Проблема с заказом<textarea name="reason" required maxlength="5000"></textarea></label><button class="btn outline small">Открыть спор</button></form><p v-if="o.payments?.length" class="muted">Тестовые операции: <span v-for="p in o.payments" :key="p.id">{{ { charge: 'оплата', refund: 'возврат', decline: 'отказ' }[p.kind] }} {{ money(p.amount) }} · </span></p><p v-if="o.dispute">Спор: {{ status[o.dispute.status] }}. {{ o.dispute.resolution }}</p><form v-if="o.buyer_id === user.id && o.status === 'completed' && !o.review" :action="'/orders/'+o.id+'/review'" method="post"><input type="hidden" name="_token" :value="csrf"><label>Оценка<select name="rating"><option v-for="n in 5" :key="n" :value="n">{{ n }} ★</option></select></label><label>Отзыв<textarea name="body" maxlength="3000"></textarea></label><button class="btn small">Оставить отзыв</button></form></div><p v-if="!payload.orders.length" class="empty">У вас пока нет заказов.</p></section>
      <section v-else-if="tab === 'listings'"><div v-for="l in payload.listings" :key="l.id" class="panel pad order"><div class="section-head"><div><span class="tag">{{ status[l.status] }}</span><h3><a :href="'/listings/'+l.id">{{ l.title }}</a></h3></div><strong>{{ money(l.price) }}</strong></div><div class="actions"><button class="btn outline small" @click="edit = edit === l.id ? null : l.id">Редактировать</button><form :action="'/listings/'+l.id+'/status'" method="post"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PATCH"><input type="hidden" name="status" :value="l.status === 'active' ? 'paused' : 'active'"><button class="btn outline small">{{ l.status === 'active' ? 'Приостановить' : 'Активировать' }}</button></form></div><form v-if="edit === l.id" :action="'/listings/'+l.id+'/edit'" method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="_token" :value="csrf"><label>Название<input name="title" :value="l.title" required></label><label>Категория<select name="category_id" required><option v-for="c in payload.categories" :value="c.id" :selected="c.id === l.category_id">{{ c.name }}</option></select></label><label>Игра<input name="game" :value="l.game"></label><label>Тип<select name="kind"><option v-for="(name,key) in kinds" :value="key" :selected="l.kind === key">{{ name }}</option></select></label><label>Цена<input name="price" type="number" min="0.01" step="0.01" :value="l.price" required></label><label>Остаток<input name="stock" type="number" min="0" :value="l.stock" required></label><label>Изображение<input name="image" type="file" accept="image/*"></label><label class="wide">Описание<textarea name="description" required :value="l.description"></textarea></label><button class="btn">Сохранить</button></form></div><p v-if="!payload.listings.length" class="empty">Объявлений пока нет.</p></section>
      <section v-else-if="tab === 'create'" class="panel pad"><h2>Новое объявление</h2><p v-if="!payload.categories.length" class="error">Для публикации администратор должен создать категорию.</p><form action="/listings" method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="_token" :value="csrf"><label>Название<input name="title" required maxlength="255"></label><label>Категория<select name="category_id" required><option value="">Выберите категорию</option><option v-for="c in payload.categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>Игра<input name="game" maxlength="100"></label><label>Тип<select name="kind"><option v-for="(name,key) in kinds" :value="key">{{ name }}</option></select></label><label>Цена, ₽<input name="price" type="number" min="0.01" step="0.01" required></label><label>Количество<input name="stock" type="number" min="0" value="1" required></label><label>Фото<input name="image" type="file" accept="image/*"></label><label class="wide">Описание<textarea name="description" required maxlength="20000"></textarea></label><button class="btn" :disabled="!payload.categories.length">Опубликовать</button></form></section>
      <section v-else-if="tab === 'favorites'"><div class="grid"><a v-for="l in payload.favorites" :key="l.id" class="card pad" :href="'/listings/'+l.id"><h3>{{ l.title }}</h3><p>{{ l.user?.name }}</p><strong>{{ money(l.price) }}</strong></a></div><p v-if="!payload.favorites.length" class="empty">Избранное пусто.</p></section><section v-else class="panel pad"><h2>Мой профиль</h2><form action="/profile" method="post"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PUT"><label>Имя<input name="name" :value="user.name" required></label><label>О себе<textarea name="bio" maxlength="2000" :value="user.bio"></textarea></label><button class="btn">Сохранить</button></form><a :href="'/sellers/'+user.id">Посмотреть публичный профиль →</a></section>
    </template>

    <template v-else-if="page === 'admin'"><h1>Управление площадкой</h1><div class="panel pad"><h2>Новая категория</h2><form action="/admin/categories" method="post" class="form-grid"><input type="hidden" name="_token" :value="csrf"><label>Название<input name="name" required></label><label>Slug (латиница)<input name="slug" required pattern="[A-Za-z0-9_-]+"></label><label>Родительская категория<select name="parent_id"><option value="">Нет</option><option v-for="c in payload.categories" :value="c.id">{{ c.name }}</option></select></label><button class="btn">Добавить</button></form></div><h2>Споры</h2><div v-for="d in payload.disputes" :key="d.id" class="panel pad order"><h3>Заказ #{{ d.order_id }} · {{ status[d.status] }}</h3><p>{{ d.reason }}</p><p>Покупатель: {{ d.order?.buyer?.name }} · Продавец: {{ d.order?.seller?.name }}</p><form v-if="d.status === 'open'" :action="'/admin/disputes/'+d.id+'/resolve'" method="post"><input type="hidden" name="_token" :value="csrf"><label>Решение<textarea name="resolution" required></textarea></label><label>Итог<select name="decision"><option value="completed">Завершить</option><option value="cancelled">Отменить</option></select></label><button class="btn small">Разрешить</button></form><p v-else>{{ d.resolution }}</p></div><h2>Пользователи</h2><div v-for="u in payload.users" :key="u.id" class="panel pad admin-row"><span>{{ u.name }} ({{ u.email }}) <small v-if="u.is_banned">— заблокирован</small></span><form v-if="u.id !== user.id" :action="'/admin/users/'+u.id+'/ban'" method="post"><input type="hidden" name="_token" :value="csrf"><button class="btn outline small">{{ u.is_banned ? 'Разблокировать' : 'Заблокировать' }}</button></form></div><h2>Модерация объявлений</h2><div v-for="l in payload.listings" :key="l.id" class="panel pad admin-row"><span><a :href="'/listings/'+l.id">{{ l.title }}</a> · {{ l.user?.name }} · {{ status[l.status] }}</span><form :action="'/admin/listings/'+l.id" method="post"><input type="hidden" name="_token" :value="csrf"><select name="status"><option v-for="v in ['active','paused','hidden']" :value="v" :selected="l.status === v">{{ status[v] }}</option></select><button class="btn outline small">Сохранить</button></form></div></template>
  </main><footer><div class="wrap">✦ GameGoods <span>Демонстрационная площадка · Реальные платежи отсутствуют</span></div></footer>
</template>
